callGraph.callee:
text
    .trim()
    .split(/\n\n+/)
    .map((chunk) => {
      const event = chunk.match(/^event: (.+)$/m)?.[1] ?? "message";
      const data = chunk.match(/^data: (.+)$/m)?.[1];
      return data ? { event, data: JSON.parse(data) as Record<string, unknown> } : null;
    })
    .filter
